// Presentation annotations use the same normalized page coordinates as the editor.
export function setupPresentation({getPage,getColor,setColor,colors,strokes,onInk,notify}) {
  const root=document.querySelector('#presentation'),slide=document.querySelector('#slide');
  let tool='view',zoom=1,pageCanvas,pageModel,stroke=null,selected=null,z=1,capturing=false;
  const toolbar=document.createElement('div');toolbar.className='present-tools';
  toolbar.innerHTML=`<div class="present-group"><button data-mode="view" class="active">↖ 이동</button><button data-mode="pen">✎ 펜</button><button data-mode="highlight">▰ 형광펜</button><button data-mode="laser">● 레이저</button></div><div class="present-group present-colors"></div><input class="present-color" type="color" aria-label="발표 필기 색상"><label>굵기 <input class="present-width" type="range" min="1" max="24" value="3" aria-label="발표 필기 굵기"></label><div class="present-group"><button data-action="out" aria-label="축소">−</button><button data-action="fit">100%</button><button data-action="in" aria-label="확대">＋</button></div><button data-action="capture">▣ 화면 캡처</button><label class="capture-import">이미지 추가<input type="file" accept="image/*" hidden></label><button data-action="undo">↶ 필기 취소</button>`;
  root.append(toolbar);
  const layer=document.createElement('div');layer.className='capture-layer';root.append(layer);
  const laser=document.createElement('div');laser.className='laser-dot';laser.hidden=true;root.append(laser);
  const custom=toolbar.querySelector('.present-color');custom.value=getColor();
  function chooseColor(c){setColor(c);custom.value=c;toolbar.querySelectorAll('.present-swatch').forEach(b=>b.classList.toggle('active',b.dataset.color===c));laser.style.setProperty('--laser',c)}
  colors.forEach(c=>{const b=document.createElement('button');b.className='present-swatch';b.dataset.color=c;b.style.background=c;b.setAttribute('aria-label','필기 색상 '+c);b.onclick=()=>chooseColor(c);toolbar.querySelector('.present-colors').append(b)});chooseColor(getColor());custom.oninput=()=>chooseColor(custom.value);
  toolbar.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{tool=b.dataset.mode;stroke=null;stopLaser();toolbar.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));root.dataset.mode=tool});
  function applyZoom(){if(!pageCanvas)return;const scale=Math.min(slide.clientWidth/pageCanvas.width,slide.clientHeight/pageCanvas.height)*zoom;pageCanvas.style.width=pageCanvas.width*scale+'px';pageCanvas.style.height=pageCanvas.height*scale+'px';slide.style.setProperty('--slide-height',pageCanvas.height*scale+'px');toolbar.querySelector('[data-action="fit"]').textContent=Math.round(zoom*100)+'%'}
  toolbar.querySelector('[data-action="out"]').onclick=()=>{zoom=Math.max(.5,zoom-.25);applyZoom()};toolbar.querySelector('[data-action="in"]').onclick=()=>{zoom=Math.min(4,zoom+.25);applyZoom()};toolbar.querySelector('[data-action="fit"]').onclick=()=>{zoom=1;applyZoom()};
  function stopLaser(){laser.hidden=true}
  function showLaser(e){laser.hidden=false;laser.style.left=e.clientX+'px';laser.style.top=e.clientY+'px';laser.style.setProperty('--laser',getColor());clearTimeout(showLaser.timer);showLaser.timer=setTimeout(stopLaser,900)}
  function wireInk(canvas,model,redraw,changed){let currentStroke=null;canvas.style.touchAction='none';canvas.onpointerdown=e=>{if(tool==='laser'){showLaser(e);return}if(!['pen','highlight'].includes(tool))return;e.preventDefault();e.stopPropagation();selected=model;canvas.setPointerCapture(e.pointerId);const r=canvas.getBoundingClientRect();currentStroke={tool,color:getColor(),width:Number(toolbar.querySelector('.present-width').value)*(tool==='highlight'?4:1)/r.width,points:[[(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height]]};model.strokes.push(currentStroke);redraw()};canvas.onpointermove=e=>{if(tool==='laser'){showLaser(e);return}if(!currentStroke)return;const r=canvas.getBoundingClientRect();currentStroke.points.push([(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height]);redraw()};canvas.onpointerup=canvas.onpointercancel=()=>{if(currentStroke){currentStroke=null;changed?.()}};canvas.onpointerleave=()=>{if(tool==='laser')stopLaser()}}
  function attach(canvas,model){pageCanvas=canvas;pageModel=model;selected=model;const base=document.createElement('canvas');base.width=canvas.width;base.height=canvas.height;base.getContext('2d').drawImage(document.querySelector('#pdf'),0,0);const redraw=()=>{const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(base,0,0);const ink=document.createElement('canvas');ink.width=canvas.width;ink.height=canvas.height;strokes(ink.getContext('2d'),model,ink.width,ink.height);ctx.drawImage(ink,0,0)};wireInk(canvas,model,redraw,onInk);applyZoom()}
  toolbar.querySelector('[data-action="undo"]').onclick=()=>{const model=selected||getPage();if(!model)return;model.strokes.pop();if(model===pageModel){attach(pageCanvas,model);onInk()}else model.redraw?.()};
  // The capture layer belongs to the presentation, not to an individual PDF page.
  function addCapture(image){const model={strokes:[]},box=document.createElement('div');box.className='capture-box';box.style.cssText=`left:15%;top:20%;width:${Math.min(440,root.clientWidth*.6)}px;aspect-ratio:${image.naturalWidth}/${image.naturalHeight};z-index:${++z}`;
    box.innerHTML='<div class="capture-handle"><span>⠿ 캡처 · 드래그하여 이동</span><button title="캡처 이미지 저장">↓</button><button title="캡처 삭제">×</button></div><canvas></canvas><button class="capture-resize" aria-label="캡처 크기 조절">↘</button>';
    const canvas=box.querySelector('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;
    const redraw=()=>{const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0);const annotation=document.createElement('canvas');annotation.width=canvas.width;annotation.height=canvas.height;strokes(annotation.getContext('2d'),model,canvas.width,canvas.height);ctx.drawImage(annotation,0,0)};model.redraw=redraw;redraw();wireInk(canvas,model,redraw);layer.append(box);selected=model;
    box.onpointerdown=()=>{box.style.zIndex=++z;selected=model};
    const buttons=box.querySelectorAll('.capture-handle button');buttons[1].onclick=()=>{box.remove();if(selected===model)selected=pageModel};buttons[0].onclick=()=>{const a=document.createElement('a');a.download='모아PDF_캡처.png';a.href=canvas.toDataURL('image/png');a.click()};
    function drag(target,resize){target.onpointerdown=e=>{if(e.target.closest('.capture-handle button'))return;e.preventDefault();e.stopPropagation();target.setPointerCapture(e.pointerId);const rect=box.getBoundingClientRect(),sx=e.clientX,sy=e.clientY;target.onpointermove=ev=>{if(resize){const w=Math.max(100,Math.min(root.clientWidth-rect.left,rect.width+ev.clientX-sx));box.style.width=w+'px'}else{box.style.left=Math.max(0,Math.min(root.clientWidth-60,rect.left+ev.clientX-sx))+'px';box.style.top=Math.max(0,Math.min(root.clientHeight-60,rect.top+ev.clientY-sy))+'px'}};target.onpointerup=target.onpointercancel=()=>{target.onpointermove=null}}}
    drag(box.querySelector('.capture-handle'),false);drag(box.querySelector('.capture-resize'),true);
  }
  function fromURL(url){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{addCapture(image);resolve()};image.onerror=reject;image.src=url})}
  toolbar.querySelector('input[type="file"]').onchange=async e=>{const f=e.target.files[0];if(!f)return;const url=URL.createObjectURL(f);try{await fromURL(url)}catch{notify('이미지를 열 수 없습니다.')}finally{URL.revokeObjectURL(url);e.target.value=''}};
  toolbar.querySelector('[data-action="capture"]').onclick=async()=>{if(capturing)return;if(!navigator.mediaDevices?.getDisplayMedia)return notify('이 브라우저는 화면 캡처를 지원하지 않습니다. 이미지 추가를 이용해 주세요.');capturing=true;root.dataset.capturing='true';let stream;try{stream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});const video=document.createElement('video');video.srcObject=stream;video.muted=true;await video.play();if(!video.videoWidth)await new Promise((resolve,reject)=>{video.onloadeddata=resolve;video.onerror=reject});const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);await fromURL(canvas.toDataURL('image/png'));video.pause();video.srcObject=null;notify('캡처를 고정했습니다. 상단 손잡이로 이동하고 오른쪽 아래에서 크기를 조절하세요.')}catch(e){notify(e.name==='NotAllowedError'?'화면 캡처가 취소되었거나 허용되지 않았습니다.':'화면 캡처를 완료하지 못했습니다. 이미지 추가를 이용해 주세요.')}finally{stream?.getTracks().forEach(t=>t.stop());capturing=false;root.dataset.capturing='false'}};
  let pan;slide.addEventListener('pointerdown',e=>{if(tool!=='view'||zoom<=1)return;slide.setPointerCapture(e.pointerId);pan={x:e.clientX,y:e.clientY,left:slide.scrollLeft,top:slide.scrollTop}});slide.addEventListener('pointermove',e=>{if(pan){slide.scrollLeft=pan.left+pan.x-e.clientX;slide.scrollTop=pan.top+pan.y-e.clientY}});slide.addEventListener('pointerup',()=>pan=null);slide.addEventListener('pointercancel',()=>pan=null);
  window.addEventListener('resize',applyZoom);root.dataset.mode=tool;
  return {attach,stopLaser};
}

